# frozen_string_literal: true

module Types
  # The shared interface for the controlled vocabulary record types.
  #
  # The types themselves are generated by `bin/rails generate controlled_vocabulary_graphql`.
  #
  # @see ControlledVocabularyRecord
  # @see Types::AbstractControlledVocabularyRecord
  module ControlledVocabularyRecordType
    include Types::BaseInterface

    description <<~TEXT
    A record (term) in one of the controlled vocabularies that solutions are described with.
    TEXT

    implements GraphQL::Types::Relay::Node
    implements ::Types::SluggableType
    implements ::Types::HasDefaultTimestampsType

    field :kind, ::Types::ControlledVocabularyKindType, null: false do
      description "Which vocabulary the record belongs to."
    end

    field :name, String, null: false do
      description "The label for the term."
    end

    field :term, String, null: false do
      description "The exact-match term used when importing and exporting CSV."
    end

    field :url_slug, String, null: false, method: :slug do
      description "The human-readable slug, as used in public URLs."
    end

    field :description, String, null: true, authorize_field: { to: :read_admin_details?, raise: false } do
      description "Internal notes about the term. Only admins can read it."
    end

    field :visibility, ::Types::VisibilityType, null: false do
      description "Whether the term appears on the public site."
    end

    field :provides, ::Types::ControlledVocabularyProvisionType, null: true do
      description "Special behavior the term provides, such as being the \"Other\" option."
    end

    field :bespoke_filter_position, Integer, null: true do
      description "The term's position in the public search filters, if it has a special order."
    end

    field :solutions_count, Integer, null: false do
      description "How many solutions use this term."
    end

    field :solution_drafts_count, Integer, null: true, authorize_field: { to: :read_admin_details?, raise: false } do
      description "How many in-progress drafts use this term. Only admins can read it."
    end

    expose_authorization_rule :update?, <<~TEXT
    Whether the current user can update this term.
    TEXT

    expose_authorization_rule :destroy?, <<~TEXT
    Whether the current user can destroy this term.
    TEXT

    expose_authorization_rule :replace?, <<~TEXT
    Whether the current user can merge this term into another.
    TEXT

    # @return [String]
    def kind = object.class.name
  end
end
